// reference matcher: echo semantics
// '*' matches remainder (possibly empty), ':' matches exactly one non-empty segment
func refMatch(pattern, path string) bool {
	ps := strings.Split(pattern, "/")
	xs := strings.Split(path, "/")
	var m func(i, j int) bool
	m = func(i, j int) bool {
		if i == len(ps) {
			return j == len(xs)
		}
		if ps[i] == "*" {
			return true
		}
		if j >= len(xs) {
			return false
		}
		if strings.HasPrefix(ps[i], ":") {
			if xs[j] == "" {
				return false
			}
			return m(i+1, j+1)
		}
		if ps[i] != xs[j] {
			return false
		}
		return m(i+1, j+1)
	}
	return m(0, 0)
}

