// expected params for a pattern matched against a path (assuming refMatch true)
func refParams(pattern, path string) map[string]string {
	ps := strings.Split(pattern, "/")
	xs := strings.Split(path, "/")
	out := map[string]string{}
	i, j := 0, 0
	for i < len(ps) {
		if ps[i] == "*" {
			out["*"] = strings.Join(xs[j:], "/")
			return out
		}
		if strings.HasPrefix(ps[i], ":") {
			out[ps[i][1:]] = xs[j]
		}
		i++
		j++
	}
	return out
}

