package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"sort"
	"strings"
	"testing"
)

type refRoute struct {
	method, pattern string
	segs            []string
}

func segsOf(p string) []string { return strings.Split(p, "/") }

// returns (matched bool, params map, priorityKey)
func refMatch2(segs []string, xs []string) (bool, map[string]string) {
	params := map[string]string{}
	i, j := 0, 0
	for i < len(segs) {
		if segs[i] == "*" {
			if j >= len(xs) {
				return false, nil
			}
			params["*"] = strings.Join(xs[j:], "/")
			return true, params
		}
		if j >= len(xs) {
			return false, nil
		}
		if strings.HasPrefix(segs[i], ":") {
			params[segs[i][1:]] = xs[j]
		} else if segs[i] != xs[j] {
			return false, nil
		}
		i++
		j++
	}
	if j != len(xs) {
		return false, nil
	}
	return true, params
}

func prioKey(segs []string) string {
	var b strings.Builder
	for _, s := range segs {
		switch {
		case s == "*":
			b.WriteString("2")
		case strings.HasPrefix(s, ":"):
			b.WriteString("1")
		default:
			b.WriteString("0")
		}
	}
	return b.String()
}

// reference result: returns (route pattern or "", status)
// status: 200-ish (matched), 405, 404
func refFind(routes []refRoute, method, path string) (string, int) {
	xs := segsOf(path)
	type cand struct {
		r refRoute
		p map[string]string
	}
	var cands []cand
	for _, r := range routes {
		ok, p := refMatch2(r.segs, xs)
		if ok {
			cands = append(cands, cand{r, p})
		}
	}
	if len(cands) == 0 {
		return "", 404
	}
	// dedupe by shape (same priority key + same length)
	best := cands[0]
	for _, c := range cands[1:] {
		if prioKey(c.r.segs) < prioKey(best.r.segs) {
			best = c
		}
	}
	if best.r.method == method {
		return best.r.pattern, 0
	}
	return "", 405
}

