 41	// echo semantics: param matches one segment (may be empty unless it is the last segment)
 42	func refMatch3(pattern, path string) (bool, []string) {
 43		segs := normSegs(pattern)
 44		xs := strings.Split(path, "/")
 45		var params []string
 46		i, j := 0, 0
 47		for i < len(segs) {
 48			if segs[i] == "*" {
 49				if j >= len(xs) {
 50					return false, nil
 51				}
 52				params = append(params, strings.Join(xs[j:], "/"))
 53				return true, params
 54			}
 55			if j >= len(xs) {
 56				return false, nil
 57			}
 58			if strings.HasPrefix(segs[i], ":") {
 59				if xs[j] == "" && j == len(xs)-1 {
 60					return false, nil
 61				}
 62				params = append(params, xs[j])
 63			} else if segs[i] != xs[j] {
 64				return false, nil
 65			}
 66			i++
 67			j++
 68		}
 69		if j != len(xs) {
 70			return false, nil
 71		}
 72		return true, params
 73	}
