 75	func kindAt(p string, i int) int {
 76		segs := normSegs(p)
 77		if i >= len(segs) {
 78			return 3
 79		}
 80		switch {
 81		case segs[i] == "*":
 82			return 2
 83		case strings.HasPrefix(segs[i], ":"):
 84			return 1
 85		default:
 86			return 0
 87		}
 88	}
