 90	func better(a, b string) bool { // is a better (higher priority) than b
 91		for i := 0; ; i++ {
 92			ka, kb := kindAt(a, i), kindAt(b, i)
 93			if ka != kb {
 94				return ka < kb
 95			}
 96			if ka == 3 {
 97				return false
 98			}
 99		}
100	}
