108	func refFind(routes []refRoute, method, path string) refResult {
109		type cand struct {
110			r      refRoute
111			params []string
112		}
113		var cands []cand
114		for _, r := range routes {
115			ok, p := refMatch3(r.pattern, path)
116			if ok {
117				cands = append(cands, cand{r, p})
118			}
119		}
120		if len(cands) == 0 {
121			return refResult{"", 404, nil}
122		}
123		best := cands[0]
124		for _, c := range cands[1:] {
125			if better(c.r.pattern, best.r.pattern) {
126				best = c
127			}
128		}
129		// all candidates with the same shape share the same tree node
130		for _, c := range cands {
131			if shapeOf(c.r.pattern) == shapeOf(best.r.pattern) && c.r.method == method {
132				return refResult{shapeOf(c.r.pattern), 0, c.params}
133			}
134		}
135		return refResult{shapeOf(best.r.pattern), 405, nil}
136	}
