 10	// reference matcher: echo semantics
 11	// '*' matches remainder (possibly empty), ':' matches exactly one non-empty segment
 12	func refMatch(pattern, path string) bool {
 13		ps := strings.Split(pattern, "/")
 14		xs := strings.Split(path, "/")
 15		var m func(i, j int) bool
 16		m = func(i, j int) bool {
 17			if i == len(ps) {
 18				return j == len(xs)
 19			}
 20			if ps[i] == "*" {
 21				// '*' consumes the remainder after the preceding '/', which may be empty
 22				// but the separator must be present in the request path
 23				return j < len(xs)
 24			}
 25			if j >= len(xs) {
 26				return false
 27			}
 28			if strings.HasPrefix(ps[i], ":") {
 29				if xs[j] == "" {
 30					return false
 31				}
 32				return m(i+1, j+1)
 33			}
 34			if ps[i] != xs[j] {
 35				return false
 36			}
 37			return m(i+1, j+1)
 38		}
 39		return m(0, 0)
 40	}
