package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"strings"
	"testing"
)

type refRoute struct {
	method, pattern string
}

func normSegs(p string) []string {
	segs := strings.Split(p, "/")
	for i, s := range segs {
		if s == "*" {
			return segs[:i+1]
		}
	}
	return segs
}

func shapeOf(p string) string {
	var b strings.Builder
	for _, s := range normSegs(p) {
		switch {
		case s == "*":
			b.WriteString("2")
		case strings.HasPrefix(s, ":"):
			b.WriteString("1")
		default:
			b.WriteString("0")
		}
	}
	return b.String()
}

func refMatch3(pattern, path string) (bool, []string) {
	segs := normSegs(pattern)
	xs := strings.Split(path, "/")
	var params []string
	i, j := 0, 0
	for i < len(segs) {
		if segs[i] == "*" {
			if j >= len(xs) {
				return false, nil
			}
			params = append(params, strings.Join(xs[j:], "/"))
			return true, params
		}
		if j >= len(xs) {
			return false, nil
		}
		if strings.HasPrefix(segs[i], ":") {
			if xs[j] == "" && j == len(xs)-1 {
				return false, nil
			}
			params = append(params, xs[j])
		} else if segs[i] != xs[j] {
			return false, nil
		}
		i++
		j++
	}
	if j != len(xs) {
		return false, nil
	}
	return true, params
}

func kindAt(p string, i int) int {
	segs := normSegs(p)
	if i >= len(segs) {
		return 3
	}
	switch {
	case segs[i] == "*":
		return 2
	case strings.HasPrefix(segs[i], ":"):
		return 1
	default:
		return 0
	}
}

func better(a, b string) bool {
	for i := 0; ; i++ {
		ka, kb := kindAt(a, i), kindAt(b, i)
		if ka != kb {
			return ka < kb
		}
		if ka == 3 {
			return false
		}
	}
}

type refResult struct {
	shape  string
	status int
	params []string
}

func refFind(routes []refRoute, method, path string) refResult {
	type cand struct {
		r      refRoute
		params []string
	}
	var cands []cand
	for _, r := range routes {
		ok, p := refMatch3(r.pattern, path)
		if ok {
			cands = append(cands, cand{r, p})
		}
	}
	if len(cands) == 0 {
		return refResult{"", 404, nil}
	}
	best := cands[0]
	for _, c := range cands[1:] {
		if better(c.r.pattern, best.r.pattern) {
			best = c
		}
	}
	for _, c := range cands {
		if shapeOf(c.r.pattern) == shapeOf(best.r.pattern) && c.r.method == method {
			return refResult{shapeOf(c.r.pattern), 0, c.params}
		}
	}
	return refResult{shapeOf(best.r.pattern), 405, nil}
}

func eq(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
