// normalize a route pattern: statics kept, params -> "p<idx>", any -> "a"
func normRoute(p string) string {
	segs := strings.Split(p, "/")
	out := make([]string, 0, len(segs))
	pi := 0
	for _, s := range segs {
		switch {
		case strings.HasPrefix(s, "*"):
			out = append(out, "a")
			return strings.Join(out, "/")
		case strings.HasPrefix(s, ":"):
			out = append(out, fmt.Sprintf("p%d", pi))
			pi++
		default:
			out = append(out, s)
		}
	}
	return strings.Join(out, "/")
}

type fr struct {
	method, pattern string
}

func normSegs2(p string) []string {
	segs := strings.Split(p, "/")
	for i, s := range segs {
		if strings.HasPrefix(s, "*") {
			return append(segs[:i], "*")
		}
	}
	return segs
}

func refMatch4(pattern, path string) (bool, []string) {
	segs := normSegs2(pattern)
	xs := strings.Split(path, "/")
	var params []string
	i, j := 0, 0
	for i < len(segs) {
		if segs[i] == "*" {
			if j >= len(xs) {
				return false, nil
			}
			params = append(params, strings.Join(xs[j:], "/"))
			return true, params
		}
		if j >= len(xs) {
			return false, nil
		}
		if strings.HasPrefix(segs[i], ":") {
			if xs[j] == "" && j == len(xs)-1 {
				return false, nil
			}
			params = append(params, xs[j])
		} else if segs[i] != xs[j] {
			return false, nil
		}
		i++
		j++
	}
	if j != len(xs) {
		return false, nil
	}
	return true, params
}

func kindAt2(p string, i int) int {
	segs := normSegs2(p)
	if i >= len(segs) {
		return 3
	}
	switch {
	case segs[i] == "*":
		return 2
	case strings.HasPrefix(segs[i], ":"):
		return 1
	default:
		return 0
	}
}

func better2(a, b string) bool {
	for i := 0; ; i++ {
		ka, kb := kindAt2(a, i), kindAt2(b, i)
		if ka != kb {
			return ka < kb
		}
		if ka == 3 {
			return false
		}
	}
}

type refRes struct {
	norm   string
	status int
	params []string
}

func refFind2(routes []fr, method, path string) refRes {
	type cand struct {
		r      fr
		params []string
	}
	var cands []cand
	for _, r := range routes {
		ok, p := refMatch4(r.pattern, path)
		if ok {
			cands = append(cands, cand{r, p})
		}
	}
	if len(cands) == 0 {
		return refRes{"", 404, nil}
	}
	best := cands[0]
	for _, c := range cands[1:] {
		if better2(c.r.pattern, best.r.pattern) {
			best = c
		}
	}
	bestNorm := normRoute(best.r.pattern)
	// ppath of the node = last registered route with the same normalized pattern
	lastNorm := bestNorm
	for _, r := range routes {
		if normRoute(r.pattern) == bestNorm {
			lastNorm = normRoute(r.pattern)
		}
	}
	for _, c := range cands {
		if normRoute(c.r.pattern) == bestNorm && c.r.method == method {
			return refRes{lastNorm, 0, c.params}
		}
	}
	return refRes{lastNorm, 405, nil}
}

func eqs(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func runFuzz4(t *testing.T, name string, routes []fr, paths []string, methods []string, rnd *rand.Rand, iterations int) int {
	e := New()
	r := e.router
	for _, x := range routes {
		r.Add(x.method, x.pattern, func(c Context) error { return nil })
	}
	violations := 0
	for i := 0; i < iterations && violations < 10; i++ {
		path := paths[rnd.Intn(len(paths))]
		method := methods[rnd.Intn(len(methods))]
		c := e.NewContext(nil, nil).(*context)
		var err error
		panicked := false
		func() {
			defer func() {
				if rec := recover(); rec != nil {
					panicked = true
					err = fmt.Errorf("PANIC: %v", rec)
				}
			}()
			r.Find(method, path, c)
			err = c.handler(c)
		}()
		if panicked {
			violations++
			fmt.Printf("[%s] PANIC method=%s path=%s\n", name, method, path)
			continue
		}
		exp := refFind2(routes, method, path)
		gotStatus := 0
		if err != nil {
