119	// bindData will bind data ONLY fields in destination struct that have EXPLICIT tag
120	func (b *DefaultBinder) bindData(destination interface{}, data map[string][]string, tag string) error {
121		if destination == nil || len(data) == 0 {
122			return nil
123		}
124		typ := reflect.TypeOf(destination).Elem()
125		val := reflect.ValueOf(destination).Elem()
126	
127		// Map
128		if typ.Kind() == reflect.Map {
129			for k, v := range data {
130				if typ.Elem().Kind() == reflect.Slice {
131					val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v))
132				} else {
133					val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v[0]))
134				}
135			}
136			return nil
137		}
138	
139		// !struct
140		if typ.Kind() != reflect.Struct {
141			return errors.New("binding element must be a struct")
142		}
143	
144		for i := 0; i < typ.NumField(); i++ {
145			typeField := typ.Field(i)
146			structField := val.Field(i)
147			if !structField.CanSet() {
148				continue
149			}
150			structFieldKind := structField.Kind()
151			inputFieldName := typeField.Tag.Get(tag)
152	
153			if inputFieldName == "" {
154				// If tag is nil, we inspect if the field is a not BindUnmarshaler struct and try to bind data into it (might contains fields with tags).
155				// structs that implement BindUnmarshaler are binded only when they have explicit tag
156				if _, ok := structField.Addr().Interface().(BindUnmarshaler); !ok && structFieldKind == reflect.Struct {
157					if err := b.bindData(structField.Addr().Interface(), data, tag); err != nil {
158						return err
159					}
160				}
161				// does not have explicit tag and is not an ordinary struct - so move to next field
162				continue
163			}
164	
165			inputValue, exists := data[inputFieldName]
166			if !exists {
167				// Go json.Unmarshal supports case insensitive binding.  However the
168				// url params are bound case sensitive which is inconsistent.  To
169				// fix this we must check all of the map values in a
170				// case-insensitive search.
171				for k, v := range data {
172					if strings.EqualFold(k, inputFieldName) {
173						inputValue = v
174						exists = true
175						break
176					}
177				}
178			}
179	
180			if !exists {
181				continue
182			}
183	
184			// Call this first, in case we're dealing with an alias to an array type
185			if ok, err := unmarshalField(typeField.Type.Kind(), inputValue[0], structField); ok {
186				if err != nil {
187					return err
188				}
189				continue
190			}
191	
192			numElems := len(inputValue)
193			if structFieldKind == reflect.Slice && numElems > 0 {
194				sliceOf := structField.Type().Elem().Kind()
195				slice := reflect.MakeSlice(structField.Type(), numElems, numElems)
196				for j := 0; j < numElems; j++ {
197					if err := setWithProperType(sliceOf, inputValue[j], slice.Index(j)); err != nil {
198						return err
199					}
200				}
201				val.Field(i).Set(slice)
202			} else if err := setWithProperType(typeField.Type.Kind(), inputValue[0], structField); err != nil {
203				return err
204	
205			}
206		}
207		return nil
208	}
