212		if ok, err := unmarshalField(valueKind, val, structField); ok {
213			return err
214		}
215	
216		switch valueKind {
217		case reflect.Ptr:
218			return setWithProperType(structField.Elem().Kind(), val, structField.Elem())
219		case reflect.Int:
220			return setIntField(val, 0, structField)
