func runTmpGzipEmpty(t *testing.T, name string, h echo.HandlerFunc) {
	e := echo.New()
	req := httptest.NewRequest(http.MethodGet, "/", nil)
	req.Header.Set(echo.HeaderAcceptEncoding, "gzip")
	rec := httptest.NewRecorder()
	c := e.NewContext(req, rec)
	mw := Gzip()
	handler := mw(h)
	if err := handler(c); err != nil {
		t.Logf("%s: handler returned err=%v", name, err)
	}
	body := rec.Body.Bytes()
	head := body
	if len(head) > 4 {
		head = head[:4]
	}
	t.Logf("%s: Body.Len=%d head=% x Content-Encoding=%q Content-Type=%q Size=%d",
		name, len(body), head, rec.Header().Get(echo.HeaderContentEncoding),
		rec.Header().Get(echo.HeaderContentType), c.Response().Size)

	// control: decompress if gzip magic
	if len(body) >= 2 && body[0] == 0x1f && body[1] == 0x8b {
		zr, err := gzip.NewReader(bytes.NewReader(body))
		if err != nil {
			t.Logf("%s: gzip.NewReader err=%v", name, err)
			return
		}
		plain, err := ioutil.ReadAll(zr)
		if err != nil {
			t.Logf("%s: gzip read err=%v", name, err)
			return
		}
		t.Logf("%s: decompressed=%q", name, string(plain))
	}
}

func TestTmpGzipEmpty(t *testing.T) {
	runTmpGzipEmpty(t, "(a) nil handler", func(c echo.Context) error { return nil })
	runTmpGzipEmpty(t, "(b) NoContent", func(c echo.Context) error { return c.NoContent(http.StatusOK) })
	runTmpGzipEmpty(t, "(c) String empty", func(c echo.Context) error { return c.String(http.StatusOK, "") })
	runTmpGzipEmpty(t, "(d) Write empty", func(c echo.Context) error { _, err := c.Response().Write([]byte{}); return err })
	runTmpGzipEmpty(t, "(e) Write test", func(c echo.Context) error { _, err := c.Response().Write([]byte("test")); return err })
	runTmpGzipEmpty(t, "(f) Blob empty", func(c echo.Context) error {
		return c.Blob(http.StatusOK, echo.MIMETextPlainCharsetUTF8, []byte{})
	})
}
EOF
